import{_ as d,C as s,o as e,c as n,a4 as l,b as r,w as a,a as o,E as f,a5 as g}from"./chunks/framework.2-Vke5-n.js";const _=JSON.parse('{"title":"","description":"","frontmatter":{"sidebarDepth":4,"author":"フューチャー株式会社","layout":"home","hero":{"name":"非同期設計ガイドライン","tagline":"Async Design Guidelines","actions":[{"theme":"brand","text":"非同期設計ガイドライン","link":"./async_guidelines.md"}]}},"headers":[],"relativePath":"documents/forAsync/index.md","filePath":"documents/forAsync/index.md"}'),x={name:"documents/forAsync/index.md"};function y(h,t,c,u,E,p){const i=s("Mermaid");return e(),n("div",null,[t[1]||(t[1]=l('<h2 id="はじめに" tabindex="-1">はじめに <a class="header-anchor" href="#はじめに" aria-label="Permalink to &quot;はじめに&quot;">​</a></h2><p>かつて、非同期処理は専門的なメッセージングミドルウェアを必要とする、一部のミッションクリティカルなシステムで採用される特別な技術と言えた。今やクラウドネイティブなサービス（例：AWS SQSなど）の登場で状況は様変わりし、応答時間の長い処理のオフロードなどを目的に、非同期処理を取り入れることは珍しくない。一方で、非同期特有の難しさは変わらず、「処理のトレース」 「デバッグ」 「リラン」が困難であり、データストアにまたがる場合のデータの整合性担保や障害発生時のリカバリは難易度が高い。</p><p>本ガイドラインは、非同期導入時のメリットを享受しつつ、「本質的な難しさ」を回避または適切に管理するための実務的な設計論点と指針を提供する。堅牢で運用しやすい非同期システムを設計するための一助になれば幸いである。</p><div class="warning custom-block"><p class="custom-block-title">免責事項</p><ul><li>有志で作成したドキュメントである。フューチャーには多様なプロジェクトが存在し、それぞれの状況に合わせて工夫された開発プロセスや高度な開発支援環境が存在する。本ガイドラインはフューチャーの全ての部署／プロジェクトで適用されているわけではなく、有志が観点を持ち寄って新たに整理したものである</li><li>相容れない部分があればその領域を書き換えて利用することを想定している。プロジェクト固有の背景や要件への配慮は、ガイドライン利用者が最終的に判断すること。本ガイドラインに必ず従うことは求めておらず、設計案の提示と、それらの評価観点を利用者に提供することを主目的としている</li><li>掲載内容および利用に際して発生した問題、それに伴う損害については、フューチャー株式会社は一切の責務を負わないものとする。掲載している情報は予告なく変更する場合がある</li></ul></div><h2 id="適用範囲" tabindex="-1">適用範囲 <a class="header-anchor" href="#適用範囲" aria-label="Permalink to &quot;適用範囲&quot;">​</a></h2><p>本ガイドラインが対象とするスコープは、バックエンドシステムにおける以下のような非同期メッセージングを用いた処理に限る。</p><ul><li>Web APIやバッチ処理からのトリガーによる非同期メッセージやキューと、その後のコンシューマー処理</li><li>ストリーミング処理は関連する領域であるが、タイムウィンドウなど特有の処理については深くは触れない</li></ul><p>以下は含まれない。</p><ul><li>各プログラミング言語で準備されている非同期処理の実装方法。例えばJavaScriptでのasync/await、Javaでのスレッド/仮想スレッド、Goのgoroutineなどには触れない</li><li>ブラウザのサービスワーカー</li></ul><h2 id="用語" tabindex="-1">用語 <a class="header-anchor" href="#用語" aria-label="Permalink to &quot;用語&quot;">​</a></h2><p>非同期処理には、メッセージキューのサービスを利用する。そうした種別や、プロダクトごとに呼び名が様々存在する。</p><table tabindex="0"><thead><tr><th style="text-align:left;">分類</th><th style="text-align:left;">キュー</th><th style="text-align:left;">Pub/Sub</th><th style="text-align:left;">ストリーミング</th></tr></thead><tbody><tr><td style="text-align:left;">説明</td><td style="text-align:left;">1:1型。1つのメッセージが1つの受信者に処理される。メッセージは処理後に削除</td><td style="text-align:left;">1:N型。1つのメッセージを複数のワーカーが受け取る。メッセージは処理後に削除</td><td style="text-align:left;">1:N型。複数のワーカーが異なる読み取り位置から再生可能。メッセージは指定期間、永続化</td></tr><tr><td style="text-align:left;">具体例</td><td style="text-align:left;">SQS, RabbitMQ</td><td style="text-align:left;">SNS、MQTT</td><td style="text-align:left;">Kafka、Kinesis</td></tr><tr><td style="text-align:left;">送信者</td><td style="text-align:left;">プロデューサー</td><td style="text-align:left;">パブリッシャー</td><td style="text-align:left;">プロデューサー</td></tr><tr><td style="text-align:left;">受信者</td><td style="text-align:left;">コンシューマー</td><td style="text-align:left;">サブスクライバー</td><td style="text-align:left;">コンシューマー</td></tr><tr><td style="text-align:left;">メッセージ格納場所</td><td style="text-align:left;">キュー</td><td style="text-align:left;">トピック</td><td style="text-align:left;">トピック/ストリーム</td></tr><tr><td style="text-align:left;">データ単位</td><td style="text-align:left;">メッセージ</td><td style="text-align:left;">メッセージ/Notification/イベント</td><td style="text-align:left;">レコード/イベント</td></tr><tr><td style="text-align:left;">順序性保証/グループ化</td><td style="text-align:left;">Message Group ID (SQS FIFOキューの場合)</td><td style="text-align:left;">-</td><td style="text-align:left;">パーティション</td></tr><tr><td style="text-align:left;">読み取り位置</td><td style="text-align:left;">Visibility Timeout</td><td style="text-align:left;">-</td><td style="text-align:left;">オフセット/シーケンス番号</td></tr></tbody></table><p>上表のように非同期処理で利用される技術や製品によって用語は様々であるが、本ガイドラインでは、一貫性を保つために以下の用語を使用する。</p>',13)),(e(),r(g,null,{default:a(()=>[f(i,{id:"mermaid-202",class:"mermaid",graph:"---%0Atitle%3A%20%E6%9C%AC%E3%82%AC%E3%82%A4%E3%83%89%E3%83%A9%E3%82%A4%E3%83%B3%E3%81%AE%E7%B5%B1%E4%B8%80%E7%94%A8%E8%AA%9E%0A---%0Agraph%20LR%0A%20%20%20%20Producer%5B%E3%83%97%E3%83%AD%E3%83%87%E3%83%A5%E3%83%BC%E3%82%B5%E3%83%BC%5D%20--%20%22%E9%80%81%E4%BF%A1%22%20---%20Message((%E3%83%A1%E3%83%83%E3%82%BB%E3%83%BC%E3%82%B8))%3B%0A%20%20%20%20Message%20--%3E%20Storage(%E3%82%AD%E3%83%A5%E3%83%BC)%3B%0A%20%20%20%20Storage%20--%20%22%E5%8F%97%E4%BF%A1%22%20--%3E%20Consumer%5B%E3%82%B3%E3%83%B3%E3%82%B7%E3%83%A5%E3%83%BC%E3%83%9E%E3%83%BC%5D%3B%0A"})]),fallback:a(()=>[...t[0]||(t[0]=[o(" Loading... ",-1)])]),_:1})),t[2]||(t[2]=l('<table tabindex="0"><thead><tr><th style="text-align:left;">用語</th><th style="text-align:left;">説明</th></tr></thead><tbody><tr><td style="text-align:left;">プロデューサー</td><td style="text-align:left;">メッセージの送信側のコンポーネント</td></tr><tr><td style="text-align:left;">コンシューマー</td><td style="text-align:left;">メッセージを受信して処理するコンポーネント</td></tr><tr><td style="text-align:left;">メッセージ</td><td style="text-align:left;">プロデューサーとコンシューマー間でやり取りされるデータの単位</td></tr><tr><td style="text-align:left;">キュー</td><td style="text-align:left;">メッセージを中継するサービス</td></tr></tbody></table><h2 id="謝辞" tabindex="-1">謝辞 <a class="header-anchor" href="#謝辞" aria-label="Permalink to &quot;謝辞&quot;">​</a></h2><p>このアーキテクチャガイドラインの作成には多くの方々にご協力いただいた。心より感謝申し上げる。</p><ul><li><strong>作成者</strong>: 真野隼記、武田大輝、亀井隆徳、佐藤尭彰、山口真明、坂本慎司、越島亮介、宮崎将太、澁川喜規</li><li><strong>レビュアー</strong>: 募集中</li></ul><h2 id="articles" tabindex="-1">Articles <a class="header-anchor" href="#articles" aria-label="Permalink to &quot;Articles&quot;">​</a></h2><ul><li>2026.02.20 <a href="https://future-architect.github.io/articles/20260220a/" target="_blank" rel="noreferrer">非同期設計ガイドラインを公開しました</a></li></ul><div class="next-page-nav"><p>次のページ: <a href="./async_guidelines.html">非同期設計ガイドライン</a></p></div>',7))])}const b=d(x,[["render",y]]);export{_ as __pageData,b as default};
